{
  "searches": [
    {
      "reason": "Identify practical probes of whether GRU4Rec uses recent coherent activity or stale interests. Compare original histories with recent-item deletion, older-item deletion, and order perturbations; measure target-rank changes and recurrent-state sensitivity using training-only held-out prefixes. Include matched random-deletion controls, final-nonpadding readout checks, and uncertainty estimates before attributing failures to recurrent memory.",
      "query": "2024 2025 2026 sequential recommendation GRU counterfactual history perturbation recency intent drift hidden state sensitivity diagnostic probes"
    },
    {
      "reason": "Develop a feedback-grounded diagnostic that separates broad relatedness from a concrete reason to choose an item now. Research structured annotation of the twenty users’ recommendations, distinguishing explicit rejection, uncertain identity, and missing evidence. Titles, descriptions, and histories can support candidate comparisons, but compatibility, redundancy, mood, and current demand must remain unknown unless supported by explicit feedback. Seek methods for validating these proxies against user judgments.",
      "query": "2024 2025 2026 recommendation diagnostic user feedback annotation actionable relevance current intent redundancy compatibility uncertainty hard negatives"
    },
    {
      "reason": "Make diagnosis trustworthy and useful for selecting training changes within one GRU4Rec model per category. Investigate whether training margins predict held-out ranking failures under popularity-matched and text-similar negatives, and compare sampled-candidate rankings with full-catalog unseen-item rankings. Seek user-level bootstrap intervals, exposure-normalized error slices, and controlled ablations connecting failures to sampling, loss, or recurrent memory, while preserving the pinned validation evaluator.",
      "query": "2024 2025 2026 recommender diagnostic validity sampled evaluation full catalog ranking hard negatives popularity bias confidence intervals controlled ablation"
    }
  ]
}
